// Defensive JSON extraction: direct → fenced → span → quarantine
function extractJSON(raw) {
  const attempts = [
    () => JSON.parse(raw),
    () => JSON.parse(raw.replace(/^```(?:json)?\n?|\n?```$/g, "").trim()),
    () => JSON.parse(raw.slice(raw.indexOf("{"), raw.lastIndexOf("}") + 1)),
  ];
  for (const tryIt of attempts) {
    try { return { ok: true, value: tryIt() }; } catch { /* next */ }
  }
  return { ok: false, raw }; // quarantine with evidence, never defaults
}
// Contract enforcement (keys + enums) happens AFTER parsing succeeds.

