function extractJSON(raw) {
  const attempts = [
    () => JSON.parse(raw),
    () => JSON.parse(raw.replace(/^```(?:json)?\n?|\n?```$/g, '').trim()),
    () => JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)),
  ];
  for (const tryIt of attempts) {
    try { return { ok: true, value: tryIt() }; } catch (e) { /* next */ }
  }
  return { ok: false, raw };
}
const cases = [
  '{"category": "billing"}',
  '```json\n{"category": "shipping"}\n```',
  'I think it is {"category": "returns"} honestly',
  'Category: billing (probably)',
];
for (const c of cases) {
  const r = extractJSON(c);
  console.log((r.ok ? 'PARSED ' + JSON.stringify(r.value) : 'QUARANTINED ' + JSON.stringify(c)));
}

